                    // Push table[i+1] onto stack (Lua arrays are 1-indexed)
                    lua_rawgeti(L, idx, i + 1);
            
                    // Convert the element
                    array[i] = ToObject<Stride.Core.Mathematics.Plane>(L, -1)!;
            
                    // Pop the element from stack
                    lua_pop(L, 1);
                }
            
                return (T)(object)array;
            }
            if (typeof(T) == typeof(Microsoft.Xna.Framework.Vector4[]))
            {
                // Get the length of the table
                var length = (int)lua_objlen(L, idx);
            
                // Create the array
                var array = new Microsoft.Xna.Framework.Vector4[length];
            
                for (int i = 0; i < length; i++)
                {
                    // Push table[i+1] onto stack (Lua arrays are 1-indexed)
                    lua_rawgeti(L, idx, i + 1);
            
                    // Convert the element
                    array[i] = ToObject<Microsoft.Xna.Framework.Vector4>(L, -1)!;
            
                    // Pop the element from stack
                    lua_pop(L, 1);
                }
            
                return (T)(object)array;
            }
            #endregion
        }

        // Handle userdata (objects, structs, arrays, etc.)
        if (luaType == LUA_TUSERDATA)
        {
            var ptr = lua_touserdata(L, idx);
            if (ptr != 0)
            {
                unsafe
                {
                    var id = *(int*)ptr;
                    return GetObject<T>(id);
                }
            }
        }

        throw new InvalidOperationException($"Cannot convert Lua type {luaType} to {typeof(T)}");
    }

    #endregion

    #region Overload Resolution

    /// <summary>
    /// Score how compatible a Lua value is with a .NET parameter type.
    /// Higher scores indicate better compatibility. -1 indicates incompatible.
    /// </summary>
    private static int ScoreParameterCompatibility<T>(lua_State L, int stackIdx)
    {
        var (luaType, dotnetType) = GetLuaStackValueType(L, stackIdx);

        // Nil can match nullable/reference types
        if (luaType == LUA_TNIL)
        {
            return !typeof(T).IsValueType || Nullable.GetUnderlyingType(typeof(T)) != null ? 0 : -1;
        }

        // Boolean matches
        if (luaType == LUA_TBOOLEAN)
        {
            if (typeof(T) == typeof(bool)) return 100; // Exact match
            return -1; // No implicit conversions from bool
        }

        // String matches
        if (luaType == LUA_TSTRING)
        {
            if (typeof(T) == typeof(string)) return 100; // Exact match
            return -1; // No implicit conversions from string
        }

        // Number matches (Lua numbers are always double)
        if (luaType == LUA_TNUMBER)
        {
            // Check if the number is an integer value (no fractional part)
            var numVal = lua_tonumber(L, stackIdx);
            var isInteger = Math.Floor(numVal) == numVal;

            if (isInteger)
            {
                // For integer values, check range compatibility and prefer appropriate integer types
                // Priority: most appropriate integer type > double > float > other integer types
                if (typeof(T) == typeof(int) && numVal >= int.MinValue && numVal <= int.MaxValue) return 100;
                if (typeof(T) == typeof(long) && numVal >= long.MinValue && numVal <= long.MaxValue) return 100;
                if (typeof(T) == typeof(double)) return 90;   // Can hold any integer
                if (typeof(T) == typeof(float) && numVal >= float.MinValue && numVal <= float.MaxValue) return 85;
                if (typeof(T) == typeof(uint) && numVal >= uint.MinValue && numVal <= uint.MaxValue) return 80;
                if (typeof(T) == typeof(ulong) && numVal >= 0 && numVal <= ulong.MaxValue) return 80;
                if (typeof(T) == typeof(short) && numVal >= short.MinValue && numVal <= short.MaxValue) return 75;
                if (typeof(T) == typeof(ushort) && numVal >= ushort.MinValue && numVal <= ushort.MaxValue) return 75;
                if (typeof(T) == typeof(byte) && numVal >= byte.MinValue && numVal <= byte.MaxValue) return 70;
                if (typeof(T) == typeof(sbyte) && numVal >= sbyte.MinValue && numVal <= sbyte.MaxValue) return 70;
                // Out of range for all integer types
                if (typeof(T) == typeof(double)) return 90;
                if (typeof(T) == typeof(float)) return 85;
                return -1; // Can't fit in any numeric type
            }
            else
            {
                // For floating-point values, prefer floating-point types
                // Priority: double > float > long > ulong > int > uint > other integer types
                if (typeof(T) == typeof(double)) return 100; // Exact match to Lua's number type
                if (typeof(T) == typeof(float)) return 90;   // Slight precision loss
                if (typeof(T) == typeof(long)) return 80;    // Large range, signed
                if (typeof(T) == typeof(ulong)) return 75;   // Large range, unsigned
                if (typeof(T) == typeof(int)) return 70;     // Standard integer
                if (typeof(T) == typeof(uint)) return 65;    // Unsigned variant
                if (typeof(T) == typeof(short)) return 60;   // Smaller range
                if (typeof(T) == typeof(ushort)) return 55;  // Smaller range, unsigned
                if (typeof(T) == typeof(byte)) return 50;    // Smallest range
                if (typeof(T) == typeof(sbyte)) return 45;   // Smallest range, signed
            }
            return -1; // Not a numeric type
        }

        // Table matches (can convert to 1D array)
        if (luaType == LUA_TTABLE)
        {
            if (typeof(T).IsArray && typeof(T).GetArrayRank() == 1)
            {
                return 50; // Table can convert to array (but we can't check element types easily)
            }
            return -1; // Tables don't convert to other types
        }

        // Userdata matches (custom .NET types)
        if (luaType == LUA_TUSERDATA && dotnetType != null)
        {
            if (typeof(T) == dotnetType) return 100; // Exact type match
            if (typeof(T).IsAssignableFrom(dotnetType)) return 80; // Inheritance/interface match
            return -1; // Type mismatch
        }

        return -1; // Unknown or incompatible
    }

    #endregion

    #region Delegate Management

    /// <summary>
    /// Keep a delegate alive to prevent GC collection while registered with Lua.
    /// </summary>
    private static lua_CFunction KeepAlive(lua_CFunction func)
    {
        // Unnecessary, static delegates are not collected
        // _delegates.Add(func);
        return func;
    }

    #endregion

    #region Event Support

    private static ConditionalWeakTable<BaseEventInvoker, DelegateRef> _eventDelegateRefs = new();

    private record DelegateRef(int FuncRef, Action Unsubscribe);

    /// <summary>
    /// Create a .NET delegate from a Lua function for event subscription.
    /// The delegate will call back into Lua when the event is raised.
    /// </summary>
    private static TDelegate CreateEventDelegate<TDelegate>(lua_State L, int funcIdx, Action<TDelegate> unregister) where TDelegate : Delegate
    {
        // Get the Lua function reference
        lua_pushvalue(L, funcIdx);
        var funcRef = luaL_ref(L, LUA_REGISTRYINDEX);

        // Create a delegate that calls back into Lua
        if (typeof(TDelegate) == typeof(System.EventHandler<System.ValueTuple<float, int>>))
        {
            var invoker = new EventInvoker2<object, System.ValueTuple<float, int>> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(System.EventHandler<System.ValueTuple<float, int>>)((arg0, arg1) => invoker.Invoke(arg0!, arg1!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(System.EventHandler<System.ValueTuple<int, float>>))
        {
            var invoker = new EventInvoker2<object, System.ValueTuple<int, float>> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(System.EventHandler<System.ValueTuple<int, float>>)((arg0, arg1) => invoker.Invoke(arg0!, arg1!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(System.EventHandler<System.ValueTuple<int, int, int>>))
        {
            var invoker = new EventInvoker2<object, System.ValueTuple<int, int, int>> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(System.EventHandler<System.ValueTuple<int, int, int>>)((arg0, arg1) => invoker.Invoke(arg0!, arg1!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(System.EventHandler<float>))
        {
            var invoker = new EventInvoker2<object, float> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(System.EventHandler<float>)((arg0, arg1) => invoker.Invoke(arg0!, arg1!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(System.EventHandler))
        {
            var invoker = new EventInvoker2<object, System.EventArgs> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(System.EventHandler)((arg0, arg1) => invoker.Invoke(arg0!, arg1!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(nfm_world_library.backend.DamageFunc))
        {
            var invoker = new EventInvoker3<nfm_world_library.mad.CarStats, int, nfm_world_library.SoftFloat.fix64> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(nfm_world_library.backend.DamageFunc)((arg0, arg1, arg2) => invoker.Invoke(arg0!, arg1!, arg2!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(nfm_world_library.backend.RoofDamageFunc))
        {
            var invoker = new EventInvoker6<nfm_world_library.mad.CarStats, int, nfm_world_library.SoftFloat.fix64, bool, int, int> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(nfm_world_library.backend.RoofDamageFunc)((arg0, arg1, arg2, arg3, arg4, arg5) => invoker.Invoke(arg0!, arg1!, arg2!, arg3!, arg4!, arg5!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(nfm_world_library.backend.SparkFunc))
        {
            var invoker = new EventInvoker8<float, float, float, float, float, float, int, int> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(nfm_world_library.backend.SparkFunc)((arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7) => invoker.Invoke(arg0!, arg1!, arg2!, arg3!, arg4!, arg5!, arg6!, arg7!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        if (typeof(TDelegate) == typeof(nfm_world_library.backend.DustFunc))
        {
            var invoker = new EventInvoker10<int, float, float, float, int, int, float, int, bool, int> { L = L, FuncRef = funcRef };
            var @delegate = (TDelegate)(Delegate)(nfm_world_library.backend.DustFunc)((arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7, arg8, arg9) => invoker.Invoke(arg0!, arg1!, arg2!, arg3!, arg4!, arg5!, arg6!, arg7!, arg8!, arg9!));
            _eventDelegateRefs.TryAdd(invoker, new DelegateRef(funcRef, () =>
            {
                unregister(@delegate);
                luaL_unref(L, LUA_REGISTRYINDEX, funcIdx);
            }));
            return @delegate;
        }
        throw new NotSupportedException($"Event delegate type {typeof(TDelegate)} is not supported");
    }

    private abstract class BaseEventInvoker
    {
        public lua_State L;
        public int FuncRef;
    }

    private sealed class EventInvoker0 : BaseEventInvoker
    {
        public void Invoke()
        {
            lua_rawgeti(L, LUA_REGISTRYINDEX, FuncRef);
            lua_pcall(L, 0, 0, 0);
        }

        ~EventInvoker0()
        {
            // Clean up Lua function reference when the invoker is garbage collected
            luaL_unref(L, LUA_REGISTRYINDEX, FuncRef);
        }
    }
    private sealed class EventInvoker2<T0, T1> : BaseEventInvoker
    {
        public void Invoke(T0 arg0, T1 arg1)
        {
            lua_rawgeti(L, LUA_REGISTRYINDEX, FuncRef);
            PushValue(L, arg0);
            PushValue(L, arg1);
            lua_pcall(L, 2, 0, 0);
        }
    
        ~EventInvoker2()
        {
            // Clean up Lua function reference when the invoker is garbage collected
            luaL_unref(L, LUA_REGISTRYINDEX, FuncRef);
        }
    }
